-- Guia "Orlando, a ordem dos parques: um complexo de cada vez" (rascunho). Gerado por tools/gerar-migration-guia.ts a partir de content/guias/orlando-a-ordem-dos-parques.json.
-- Entra como rascunho: publique pelo painel (/admin-blog.html) depois de conferir a pré-visualização.
INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('4d0cb701-783e-4706-ae16-6584c62b2cf6', 'orlando-a-ordem-dos-parques', 'draft', 'americas', 'Orlando, a ordem dos parques: um complexo de cada vez', 'um complexo de cada vez', 'Sete dias de parques em Orlando, primeiro a Disney e depois a Universal, com visto americano, ingressos e Park-to-Park explicados e o guia em PDF para baixar de graça.', 'Sete dias de parques na ordem certa, visto americano, ingressos e o que muda com o Park-to-Park, conferidos em outubro de 2026, e o guia completo para levar no celular.', 'Orlando', NULL, '/assets/blog/orlando-parques.jpg', '/assets/blog/orlando-parques-m.jpg', 'Prédios do centro de Orlando e a fonte do Lago Eola, com céu azul e nuvens', 0, '[{"t":"pdf","href":"/guias/orlando-a-ordem-dos-parques.pdf","note":"PDF de 16 páginas, uma por parque, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"O segredo de Orlando é agrupar os dias por complexo: **primeiro os quatro parques da Disney, depois os três da Universal**. Assim você não cruza a cidade todo dia, e ainda sobra um dia de descanso no meio."},{"t":"tip","items":["**Tire o visto primeiro.** Brasileiro precisa de visto americano, até para fazer só uma conexão nos Estados Unidos. Só depois compre ingressos e hotel.","**Compre os ingressos com data:** o preço muda conforme o dia.","**Quer andar no trem do Harry Potter?** O ingresso tem de ser Park-to-Park.","**Guia independente:** a Rota Certa não tem vínculo com a Disney nem com a Universal."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"A ordem dos parques","label":"O roteiro"},{"t":"p","text":"Um complexo de cada vez, com um dia de descanso no meio. Esta é a ordem sugerida pela Rota Certa:"},{"t":"ul","items":["**Dia 1:** Magic Kingdom (Disney)","**Dia 2:** EPCOT (Disney)","**Dia 3:** Hollywood Studios (Disney)","**Dia 4:** Animal Kingdom (Disney)","**Descanso ou compras:** dia livre","**Dia 5:** Universal Studios Florida (Universal)","**Dia 6:** Islands of Adventure (Universal)","**Dia 7:** Epic Universe (Universal)"]},{"t":"p","text":"**Por que nessa ordem:** na Disney, o castelo abre a viagem com a energia lá em cima. Nos dias 5 e 6, os dois parques ligados pelo Hogwarts Express ficam juntos, e o Epic Universe, o mais novo, fecha a viagem. Com menos dias, corte de trás para frente e mantenha os complexos juntos."},{"t":"h","text":"Magic Kingdom","label":"Dia 1 · Disney"},{"t":"p","text":"O parque do castelo e das atrações clássicas."},{"t":"img","src":"/assets/blog/orlando-magic-kingdom.jpg","alt":"Torres azuis e cor-de-rosa do castelo do Magic Kingdom contra um céu azul com nuvens","caption":"O castelo do Magic Kingdom.","credit":"Foto: Hailey Smith / Pexels","w":1000,"h":750},{"t":"ul","items":["**Principal:** o castelo e as atrações clássicas.","**Leve:** protetor solar, capa de chuva e carregador.","**Opcional:** fila paga (Lightning Lane).","**O horário muda por dia:** confira na véspera o horário do parque e a programação da noite no site ou no aplicativo oficial da Disney."]},{"t":"tip","items":["**Como chegar:** de carro, estacione no Transportation and Ticket Center e siga de monotrilho ou barca até a entrada.","**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro, da abertura aos shows da noite. Esforço alto: muitas horas em pé."],"title":"Para planejar o Dia 1"},{"t":"passeio","busca":"Magic Kingdom Orlando","title":"Ingressos e passeios no Magic Kingdom"},{"t":"h","text":"EPCOT","label":"Dia 2 · Disney"},{"t":"p","text":"A esfera da Spaceship Earth e uma volta ao mundo em 11 países."},{"t":"img","src":"/assets/blog/orlando-epcot.jpg","alt":"Detalhe da grande esfera prateada do EPCOT, com painéis triangulares refletindo o céu azul","caption":"A grande esfera do EPCOT, a Spaceship Earth.","credit":"Foto: El Yazid Kabbaj / Pexels","w":1000,"h":750},{"t":"ul","items":["**World Showcase:** México, Noruega, China, Alemanha, Itália, Estados Unidos, Japão, Marrocos, França, Reino Unido e Canadá.","**Principal:** Spaceship Earth e o World Showcase.","**Leve:** tênis confortável e garrafa de água.","**Opcional:** jantar num dos países do World Showcase.","**Dica da Rota Certa:** faça as atrações de manhã e deixe a volta pelos países para a tarde, terminando com o jantar."]},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro. Esforço moderado: muita caminhada em volta do lago."],"title":"Para planejar o Dia 2"},{"t":"passeio","busca":"EPCOT Orlando","title":"Ingressos e passeios no EPCOT"},{"t":"h","text":"Hollywood Studios","label":"Dia 3 · Disney"},{"t":"p","text":"Cinema, Star Wars e Toy Story num parque só."},{"t":"img","src":"/assets/blog/orlando-hollywood-studios.jpg","alt":"Rua com palmeiras altas e pessoas caminhando, com uma torre rosada ao fundo, no Hollywood Studios","caption":"Uma rua com palmeiras no Hollywood Studios.","credit":"Foto: Niki Inclan / Pexels","w":1000,"h":750},{"t":"ul","items":["**Áreas:** Star Wars: Galaxy''s Edge e Toy Story Land.","**Leve:** capa de chuva, porque as tardes de verão costumam ter pancadas.","**Opcional:** fila paga (Lightning Lane).","**Dica da Rota Certa:** chegue antes da abertura e vá direto à atração mais disputada. A fila cresce rápido."]},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro. Esforço moderado."],"title":"Para planejar o Dia 3"},{"t":"passeio","busca":"Hollywood Studios Orlando","title":"Ingressos e passeios no Hollywood Studios"},{"t":"h","text":"Animal Kingdom","label":"Dia 4 · Disney"},{"t":"p","text":"A Árvore da Vida, o safári e o mundo de Avatar."},{"t":"img","src":"/assets/blog/orlando-animal-kingdom.jpg","alt":"A Árvore da Vida do Animal Kingdom vista entre folhas grandes de bananeira","caption":"A Árvore da Vida, do Animal Kingdom, entre a folhagem.","credit":"Foto: Chris S / Pexels","w":1000,"h":750},{"t":"ul","items":["**Destaques:** Kilimanjaro Safaris e Pandora, The World of Avatar.","**Leve:** boné e protetor solar.","**Opcional:** fila paga (Lightning Lane).","**Dica da Rota Certa:** faça o safári cedo, quando os animais costumam estar mais ativos."]},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** de manhã cedo ao fim da tarde. Esforço moderado.","**Depois deste dia, descanse:** quatro dias seguidos de parque cansam. Um dia livre antes da Universal ajuda, principalmente com crianças."],"title":"Para planejar o Dia 4"},{"t":"passeio","busca":"Animal Kingdom Orlando","title":"Ingressos e passeios no Animal Kingdom"},{"t":"h","text":"Universal Studios Florida","label":"Dia 5 · Universal"},{"t":"p","text":"Atrações de filmes e o Beco Diagonal, do mundo de Harry Potter."},{"t":"img","src":"/assets/blog/orlando-universal-studios.jpg","alt":"Multidão caminhando entre palmeiras e guarda-sóis, rumo a prédios coloridos e uma montanha-russa ao fundo, no Universal Studios","caption":"A entrada do Universal Studios, em Orlando.","credit":"Foto: Dominik Gryzbon / Pexels","w":1000,"h":653},{"t":"ul","items":["**Harry Potter:** Diagon Alley e a estação King''s Cross, de onde sai o Hogwarts Express.","**Leve:** o ingresso Park-to-Park, para o trem.","**Opcional:** fila paga (Express)."]},{"t":"tip","items":["O Hogwarts Express liga a King''s Cross, neste parque, à estação de Hogsmeade, no Islands of Adventure. Com ingresso de um parque por dia, você não entra no trem."],"title":"O trem só embarca quem tem Park-to-Park"},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro. Esforço alto."],"title":"Para planejar o Dia 5"},{"t":"passeio","busca":"Universal Studios Florida","title":"Ingressos e passeios no Universal Studios"},{"t":"h","text":"Islands of Adventure","label":"Dia 6 · Universal"},{"t":"p","text":"Hogsmeade, aos pés do castelo de Hogwarts, e o outro lado do trem."},{"t":"img","src":"/assets/blog/orlando-islands-of-adventure.jpg","alt":"Torre de pedra em forma de farol, com montanha-russa verde e prédios de vidro ao fundo, num dia nublado","caption":"A torre da entrada do Islands of Adventure.","credit":"Foto: Dominik Gryzbon / Pexels","w":1000,"h":665},{"t":"ul","items":["**Harry Potter:** Hogsmeade e a estação do Hogwarts Express.","**Leve:** roupa extra, porque algumas atrações molham.","**Opcional:** fila paga (Express).","**Ideia da própria Universal:** comece em Hogsmeade, pegue o trem para o Beco Diagonal no meio do dia e volte a Hogsmeade à noite."]},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro. Esforço alto: montanhas-russas e filas."],"title":"Para planejar o Dia 6"},{"t":"passeio","busca":"Islands of Adventure Orlando","title":"Ingressos e passeios no Islands of Adventure"},{"t":"h","text":"Epic Universe","label":"Dia 7 · Universal"},{"t":"p","text":"O parque mais novo da Universal, aberto em 22/5/2025."},{"t":"ul","items":["**Cinco mundos:** Celestial Park, Super Nintendo World, Ministry of Magic (Harry Potter), Isle of Berk (Como Treinar o seu Dragão) e Dark Universe.","**Leve:** celular carregado e o aplicativo oficial instalado.","**Opcional:** fila paga (Express)."]},{"t":"tip","items":["Ele não faz parte do Park-to-Park dos outros dois parques. Compre o dia do Epic à parte ou num ingresso de 3 parques que o inclua."],"title":"O Epic Universe tem ingresso próprio"},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** o dia inteiro. Esforço alto."],"title":"Para planejar o Dia 7"},{"t":"passeio","busca":"Epic Universe Orlando","title":"Ingressos e passeios no Epic Universe"},{"t":"h","text":"Ingressos e Park-to-Park","label":"Antes de comprar"},{"t":"p","text":"Os dois complexos vendem por data, e o preço muda conforme o dia."},{"t":"ul","items":["**Disney:** o ingresso é de data marcada, e o calendário do site mostra os dias mais baratos do mês. Com ingresso de data marcada, não precisa reservar o parque.","**Park Hopper (Disney):** é opcional e deixa visitar mais de um parque no mesmo dia.","**Park-to-Park (Universal):** permite ir do Universal Studios ao Islands of Adventure no mesmo dia. É o único jeito de andar no Hogwarts Express.","**Epic Universe:** a Universal vende ingressos de 3 parques que incluem o Epic Universe, com um dia em cada parque."]},{"t":"p","text":"**Quando o Park-to-Park vale a pena:** se o trem do Harry Potter é importante para você ou para as crianças. Sem ele, um parque por dia sai mais barato. Compre só nos sites oficiais ou com agências autorizadas, e desconfie de ingresso usado ou muito barato."},{"t":"h","text":"Visto americano","label":"Antes de ir"},{"t":"p","text":"**Sem visto, não embarca.** Todo brasileiro precisa de visto para os Estados Unidos, inclusive para fazer só uma conexão. O Brasil não faz parte do programa de isenção de visto."},{"t":"ul","items":["**Como pedir:** o visto de turismo é o B1/B2. O pedido é feito pelo site oficial de agendamento, com uma taxa paga antes, e em geral há entrevista no consulado.","**Renovação pode dispensar a entrevista:** quem tem visto B1/B2 válido ou vencido há menos de 12 meses, e nunca teve recusa, pode pedir a renovação sem entrevista. O consulado ainda pode chamar."]},{"t":"tip","items":["Passaporte válido com o visto B1/B2.","Seguro viagem com cobertura médica alta.","Ingressos com data, comprados nos sites oficiais.","Carteira de motorista brasileira, se for alugar carro.","Adaptador de tomada americana."],"title":"Checklist antes de embarcar"},{"t":"p","text":"Taxa e prazos mudam: confira no site oficial da Embaixada antes de agendar."},{"t":"h","text":"Carro, dinheiro e clima","label":"Na prática"},{"t":"ul","items":["**Carro:** na Flórida, o visitante estrangeiro dirige com a carteira de motorista válida do seu país, em mãos. As locadoras têm regras próprias: confira antes de reservar. Os parques cobram estacionamento.","**Imposto fora da etiqueta:** os preços nas lojas não incluem imposto. Em Orange County, onde fica a Universal, o imposto sobre vendas é de 6,5%. Dólar pela PTAX de 14/10/2026: US$ 1 = R$ 5,04.","**Tomada e voltagem:** os Estados Unidos usam 120 V e tomada de pinos chatos (tipos A e B). Plugue brasileiro não encaixa: leve adaptador e confira se o aparelho é bivolt.","**Furacões:** a temporada vai de 1/6 a 30/11, com mais atividade de meados de agosto a meados de outubro. Nessa época, viaje com seguro e acompanhe o National Hurricane Center."]},{"t":"carro"},{"t":"h","text":"Orçamento","label":"Planejamento"},{"t":"p","text":"O preço da passagem não é o preço da viagem. Some estes itens antes de reservar:"},{"t":"ul","items":["Passagens, visto, hospedagem e seguro viagem.","Carro e estacionamento.","Ingressos dos parques, alimentação e imprevistos."]},{"t":"p","text":"Os ingressos têm preço por data: simule nos sites oficiais com as suas datas. Some 6,5% de imposto nas compras em Orange County. No cartão entram o IOF e o câmbio do seu banco. A tabela de orçamento pronta para preencher está no guia em PDF."},{"t":"pdf","href":"/guias/orlando-a-ordem-dos-parques.pdf","note":"Leve a ordem dos parques, o checklist e a tabela de orçamento no celular. Grátis, sem cadastro."},{"t":"tip","items":["Visto: [Embaixada dos EUA, isenção de visto](https://br.usembassy.gov/visa-waiver-program/) e [vistos de não imigrante](https://br.usembassy.gov/non-immigrant-visas-overview/)","[Disney: os quatro parques](https://disneyworld.disney.go.com/destinations/all-parks/)","[Disney: ingressos com data e Park Hopper](https://disneyworld.disney.go.com/guest-services/park-reservations/)","[Disney: monotrilho e transporte](https://disneyworld.disney.go.com/guest-services/monorail-transportation/)","[Disney: países do EPCOT](https://disneyworld.disney.go.com/attractions/epcot/kidcot-fun-stops/)","[Universal: guia do Hogwarts Express](https://www.universalorlando.com/contentdata/uor/en/us/files/Documents/universal-orlando-riders-guide.pdf)","[Universal: um dia no mundo de Harry Potter](https://blog.universalorlando.com/things-to-do/how-to-a-day-in-the-wizarding-world-of-harry-potter)","[Universal: mapa do Epic Universe](https://www.universalorlando.com/contentdata/uor/en/us/files/Documents/universal-epic-universe-park-map-english.pdf)","[Carteira de motorista: FLHSMV](https://www.flhsmv.gov/driver-licenses-id-cards/visiting-florida-faqs/)","[Imposto: Departamento da Receita da Flórida](https://floridarevenue.com/Forms_library/current/dr15dss_26.pdf)","[Furacões: National Hurricane Center](https://www.nhc.noaa.gov/climo/)","[Tomadas: IEC](https://www.iec.ch/world-plugs)","[Câmbio: Banco Central (PTAX)](https://olinda.bcb.gov.br/olinda/servico/PTAX/versao/v1/odata/)"],"title":"Fontes oficiais, conferidas em 14/10/2026"},{"t":"p","text":"Horários, preços e regras mudam: confira nos sites acima antes de comprar. A ordem dos parques, o dia de descanso, os tempos, o esforço e as dicas são recomendações da Rota Certa. Este é um guia independente: a Rota Certa não tem vínculo com a Disney nem com a Universal, e os nomes de parques e atrações pertencem aos seus donos."},{"t":"p","text":"Foto de capa: Sid Dalal / Pexels."},{"t":"whatsapp"},{"t":"contato"},{"t":"afiliado"}]', 8);
